const EDITABLE_FIELDS = new Set([
  'enabled',
  'ldapProvider',
  'ldapUrl',
  'ldapPort',
  'ldapBaseDN',
  'ldapGroupBaseDN',
  'ldapBindDN',
  'ldapTlsRejectUnauth',
  'fieldMappings',
  'syncBatchSize',
  'deltaSyncEnabled',
  'passwordSyncEnabled',
  'deleteUserInAdEnabled',
  'logLevel',
]);

const PUBLIC_READ_FIELDS = new Set([
  ...EDITABLE_FIELDS,
  'connectivityMode',
  'lastSyncStatus',
  'lastSyncTime',
  'lastSyncStats',
  'lastSyncError',
]);

function selectFields(config, allowedFields) {
  return Object.fromEntries(
    Object.entries(config || {})
      .filter(([key]) => allowedFields.has(key)),
  );
}

export function sanitizeConfigResponse(config) {
  if (!config) return config;
  return selectFields(config, PUBLIC_READ_FIELDS);
}

export function discardServerOwnedConfig(config) {
  return selectFields(config, EDITABLE_FIELDS);
}
