/**
 * The one way to write the stored adSyncConfig item (amfa-470).
 *
 * The whole config is a single JSON string in DynamoDB, so every write is a
 * read-modify-write of the entire value. Writers used to each do their own
 * unconditional GetItem + UpdateItem, so any two of them racing (an admin
 * PUT, a VPN change, the sync worker's status) silently reverted the other.
 * Two rules keep it safe:
 *
 * - Conditional on the value just read: a write that lands between our read
 *   and our write is never reverted. On a conflict the read is repeated and
 *   makePatch is re-applied to the fresh value.
 * - Scoped to a run id when one is given: whoever starts a sync (Sync Now or
 *   the scheduled dispatcher) stamps the config with a fresh runId while
 *   marking it 'in_progress'. A worker carrying a runId writes only while
 *   the marker is still its own; a newer run owns the marker otherwise and
 *   its own worker will report, so the UI polling for the newer run never
 *   stops on an older run's result.
 *
 * `makePatch(config)` returns the fields to set (a value of undefined
 * deletes the field), or null to leave the item untouched.
 *
 * Returns the config as written, the config as read when makePatch declined,
 * or null when there is no config (unless createIfMissing) or the marker
 * belongs to another run.
 */
import { GetItemCommand, UpdateItemCommand } from '@aws-sdk/client-dynamodb';

const WRITE_ATTEMPTS = 3;

export async function updateAdSyncConfig(
  dynamodbClient, tenantId, makePatch, { runId = null, createIfMissing = false } = {},
) {
  const key = { id: { S: tenantId }, configtype: { S: 'adSyncConfig' } };
  for (let attempt = 1; ; attempt++) {
    const item = await dynamodbClient.send(new GetItemCommand({
      TableName: process.env.CONFIG_TABLE, Key: key, ConsistentRead: true,
    }));
    const previous = item.Item?.value?.S;
    if (!previous && !createIfMissing) return null;
    const stored = previous ? JSON.parse(previous) : {};
    if (runId && stored.lastSyncRunId !== runId) return null;
    const patch = makePatch(stored);
    if (!patch) return stored;
    const config = { ...stored, ...patch };
    for (const [k, v] of Object.entries(patch)) if (v === undefined) delete config[k];
    try {
      await dynamodbClient.send(new UpdateItemCommand({
        TableName: process.env.CONFIG_TABLE,
        Key: key,
        UpdateExpression: 'SET #val = :val',
        ConditionExpression: previous ? '#val = :prev' : 'attribute_not_exists(#val)',
        ExpressionAttributeNames: { '#val': 'value' },
        ExpressionAttributeValues: {
          ':val': { S: JSON.stringify(config) },
          ...(previous ? { ':prev': { S: previous } } : {}),
        },
      }));
      return config;
    } catch (err) {
      if (err.name !== 'ConditionalCheckFailedException' || attempt >= WRITE_ATTEMPTS) throw err;
    }
  }
}
